// Collapse today's feed items into one email.
// Runs once for all items: the RSS node emits one item per article, this
// node emits a single item carrying the finished subject and HTML body.

const MAX_ITEMS = 15;
const WINDOW_HOURS = 24;
const cutoff = Date.now() - WINDOW_HOURS * 60 * 60 * 1000;

const articles = $input.all()
  .map((entry) => entry.json)
  .filter((article) => {
    // Feeds that omit or mangle the date still get through; better a
    // duplicate in the digest than a silently dropped article.
    const published = Date.parse(article.isoDate || article.pubDate || '');
    return Number.isNaN(published) ? true : published >= cutoff;
  })
  .slice(0, MAX_ITEMS);

// Returning nothing ends this branch, so no email is sent on a quiet day.
if (articles.length === 0) {
  return [];
}

const escapeHtml = (value) =>
  String(value ?? '').replace(/[&<>"]/g, (char) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
  })[char]);

const listItems = articles
  .map((article) => {
    const title = escapeHtml(article.title || 'Untitled');
    const link = escapeHtml(article.link || '#');
    const when = article.isoDate ? new Date(article.isoDate).toUTCString() : '';
    const stamp = when ? ` <span style="color:#888">&mdash; ${escapeHtml(when)}</span>` : '';
    return `  <li style="margin-bottom:8px"><a href="${link}">${title}</a>${stamp}</li>`;
  })
  .join('\n');

const today = new Date().toISOString().slice(0, 10);

const html = [
  '<div style="font-family:system-ui,-apple-system,sans-serif;max-width:640px">',
  `  <h2 style="margin-bottom:4px">Daily digest &mdash; ${today}</h2>`,
  `  <p style="color:#666;margin-top:0">${articles.length} item(s) in the last ${WINDOW_HOURS} hours.</p>`,
  '  <ul style="padding-left:18px">',
  listItems,
  '  </ul>',
  '</div>',
].join('\n');

return [
  {
    json: {
      subject: `Daily digest — ${articles.length} new item(s)`,
      html,
      count: articles.length,
    },
  },
];
